export default async function install(app){const mount=app.getMount('berlin-esg-controls');const clear=document.createElement('button');clear.type='button';clear.textContent='Leeren';clear.setAttribute('aria-label','Standort und Analysen leeren');clear.style.cssText='height:39px;padding:0 12px;border:1px solid #657381;border-radius:4px;background:#222a32;color:#e6edf2;cursor:pointer;font:600 12px "Avenir Next Pro",Avenir,sans-serif;';const user=document.createElement('span');user.setAttribute('aria-label','ArcGIS-Anmeldestatus');user.style.cssText='margin-left:auto;padding:0 4px;color:#d3dce3;font:500 12px "Avenir Next Pro",Avenir,sans-serif;white-space:nowrap;min-width:0;';user.textContent='ArcGIS · prüfe Anmeldung …';let active=true;function attach(){if(!active)return;const bar=mount.firstElementChild;if(!bar)return;const search=[...bar.children].find(e=>e.tagName==='BUTTON'&&e.textContent==='Suchen');if(!search)return;if(clear.parentElement!==bar)search.after(clear);if(user.parentElement!==bar)bar.append(user);}const observer=new MutationObserver(attach);observer.observe(mount,{childList:true});attach();function doClear(){window.dispatchEvent(new Event('esg-clear-request'));return {status:'cleared',scope:'Standort und Analysen'};}clear.addEventListener('click',doClear);app.actions.register('esg-header-clear',doClear);app.actions.register('esg-header-state',()=>({button:clear.textContent,user:user.textContent,buttonNextToSearch:clear.previousElementSibling?.textContent==='Suchen',inlineUser:mount.firstElementChild?.contains(user)||false}));app.onCleanup(()=>{active=false;observer.disconnect();clear.removeEventListener('click',doClear);clear.remove();user.remove();});const Portal=await app.import('esri/portal/Portal');try{const portal=new Portal({url:app.portalUrl||'https://www.arcgis.com'});await portal.load();if(!active)return;const p=portal.user;user.textContent=p?'ArcGIS · '+(p.fullName||p.username):'ArcGIS · nicht angemeldet';user.title=p?'Angemeldet: '+(p.fullName||p.username):'Keine ArcGIS-Anmeldung erkannt';}catch{if(active){user.textContent='ArcGIS · Status nicht verfügbar';user.title='Anmeldestatus konnte nicht geladen werden';}}}